function canonicalOrder(value) {
  const ordered = [];
  for (const char of value) {
    const ccc = UNICODE_COMBINING_MAP.get(char) || 0;
    if (ccc === 0) {
      ordered.push(char);
      continue;
    }
    let index = ordered.length;
    while (index > 0) {
      const previous = UNICODE_COMBINING_MAP.get(ordered[index - 1]) || 0;
      if (previous === 0 || previous <= ccc) break;
      index -= 1;
    }
    ordered.splice(index, 0, char);
  }
  return ordered;
}

function normalizeNFKC16(value) {
  let decomposed = "";
  for (const char of String(value || "")) {
    decomposed += UNICODE_NFKD_MAP.get(char) || char;
  }
  const ordered = canonicalOrder(decomposed);
  const result = [];
  let starterIndex = -1;
  let lastClass = 0;
  for (const char of ordered) {
    const ccc = UNICODE_COMBINING_MAP.get(char) || 0;
    if (starterIndex >= 0 && (lastClass < ccc || lastClass === 0)) {
      const composite = UNICODE_COMPOSITION_MAP.get(result[starterIndex] + char);
      if (composite) {
        result[starterIndex] = composite;
        continue;
      }
    }
    if (ccc === 0) {
      starterIndex = result.length;
      lastClass = 0;
    } else {
      lastClass = ccc;
    }
    result.push(char);
  }
  return result.join("");
}

export function casefold(value) {
  const normalized = normalizeNFKC16(value);
  let result = "";
  for (const char of normalized) {
    result += UNICODE_CASEFOLD_MAP.get(char) || char;
  }
  return result;
}
